<?php declare(strict_types=1); $allCounted=true;foreach($stocktakeItems as $si){if($si['counted_quantity']===null){$allCounted=false;break;}} ?>
<div class="module-toolbar"><div><p class="module-intro"><?= kd_e($stocktake['warehouse_name']) ?> · <?= kd_e($stocktake['stocktake_number']) ?></p></div><a class="btn secondary action-link" href="index.php?page=warehouses&action=stocktakes">← Sayım listesi</a></div>
<?php if($errors): ?><div class="alert"><?= kd_e(implode(' ',$errors)) ?></div><?php endif; ?>
<div class="stats"><div class="stat-card"><span>Ürün sayısı</span><strong><?= count($stocktakeItems) ?></strong></div><div class="stat-card"><span>Sayımı girilen</span><strong><?= count(array_filter($stocktakeItems,static fn($i)=>$i['counted_quantity']!==null)) ?></strong></div><div class="stat-card"><span>Durum</span><strong><?= $stocktake['status']==='completed'?'Tamamlandı':'Taslak' ?></strong></div></div>
<?php if($stocktake['status']==='draft'&&kd_can('warehouses.manage')): ?><section class="panel"><div class="form-section-title"><div><h3>Fiziksel sayım miktarları</h3><p>Sayım miktarlarını girin ve kaydedin. Eksik satırları daha sonra tamamlayabilirsiniz.</p></div></div><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="save_stocktake"><input type="hidden" name="stocktake_id" value="<?= (int)$stocktake['id'] ?>"><div class="table-wrap"><table class="data-table"><thead><tr><th>Ürün</th><th>Stok kodu</th><th>Sistem miktarı</th><th>Fiziksel sayım</th><th>Fark</th></tr></thead><tbody><?php foreach($stocktakeItems as $item): ?><tr><td><strong><?= kd_e($item['product_name']) ?></strong><small class="table-sub"><?= kd_e($item['unit']) ?></small></td><td><?= kd_e($item['sku']?:'—') ?></td><td><?= number_format((float)$item['expected_quantity'],3,',','.') ?></td><td><input type="number" name="counted_qty[<?= (int)$item['product_id'] ?>]" min="0" step="0.001" value="<?= $item['counted_quantity']===null?'':kd_e($item['counted_quantity']) ?>" placeholder="Sayım miktarı"></td><td><?php if($item['variance']!==null): ?><strong class="<?= (float)$item['variance']<0?'stock-low':'' ?>"><?= number_format((float)$item['variance'],3,',','.') ?></strong><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$stocktakeItems): ?><tr><td colspan="5" class="empty-state">Bu depoda sayılacak aktif stok takipli ürün bulunamadı.</td></tr><?php endif; ?></tbody></table></div><div class="form-actions"><button class="btn secondary">Sayım girişlerini kaydet</button></div></form>
<form method="post" onsubmit="return confirm('Sayım farkları depo stoklarına uygulansın mı? Bu işlem tamamlandıktan sonra değiştirilemez.')"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="complete_stocktake"><input type="hidden" name="stocktake_id" value="<?= (int)$stocktake['id'] ?>"><div class="form-actions"><button class="btn primary" <?= !$allCounted||!$stocktakeItems?'disabled':'' ?>>Sayımı tamamla ve farkları uygula</button></div><small class="muted">Tamamlama öncesinde sistem stoklarında sayım başlangıcından sonra hareket olup olmadığı da kontrol edilir.</small></form></section><?php else: ?>
<section class="panel"><div class="panel-head"><div><span class="eyebrow">SAYIM SONUCU</span><h3><?= $stocktake['status']==='completed'?'Kesinleşmiş sayım':'Sayım görüntüleme' ?></h3></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ürün</th><th>Sistem miktarı</th><th>Fiziksel sayım</th><th>Fark</th></tr></thead><tbody><?php foreach($stocktakeItems as $item): ?><tr><td><?= kd_e($item['product_name']) ?></td><td><?= number_format((float)$item['expected_quantity'],3,',','.') ?></td><td><?= $item['counted_quantity']===null?'—':number_format((float)$item['counted_quantity'],3,',','.') ?></td><td><?= $item['variance']===null?'—':number_format((float)$item['variance'],3,',','.') ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($stocktake['completed_at']): ?><p class="muted">Tamamlanma: <?= kd_e(date('d.m.Y H:i',strtotime((string)$stocktake['completed_at']))) ?></p><?php endif; ?></section><?php endif; ?>
